  ('bd719745-5c20-4605-83d4-2ea0ff5d0c80', 'the-lighthouse-films', 'The Lighthouse Films', 'Photography', 'Cinematic wedding films & timeless portraits', 'Mumbai', array['Mumbai','Goa','Udaipur','Destination']::text[], 4.9, 218, '₹3,50,000', '₹₹₹₹', true, array['Cinematic','Editorial','Candid']::text[], 'An award-winning studio crafting cinematic wedding films and editorial portraiture for luxury Indian celebrations across the globe. We tell your story with restraint, warmth and an eye for light.', '@lighthousefilms', 'lighthousefilms.in', 'Booking 2025–2026', 'linear-gradient(140deg, #0f2c1f 0%, #2d6a4f 60%, #c9a227 130%)', 'linear-gradient(135deg, #1b4332 0%, #2d6a4f 55%, #40916c 100%)', array['linear-gradient(135deg, #1b4332 0%, #2d6a4f 55%, #40916c 100%)','linear-gradient(140deg, #0f2c1f 0%, #2d6a4f 60%, #c9a227 130%)','linear-gradient(135deg, #2d6a4f 0%, #d8b961 70%, #f6eed4 100%)','linear-gradient(135deg, #8a6d1f 0%, #c9a227 60%, #ecdcae 100%)','linear-gradient(140deg, #1b4332 0%, #d99aa0 130%)','linear-gradient(135deg, #d99aa0 0%, #e8b4b8 55%, #f9e9e6 100%)']::text[]),
